                                                                                                                                                                                                                                                                                                                                                                     'parametrierter '
                                                                                                                                                                                                                                                                                                                                                                     'Verteil- '
                                                                                                                                                                                                                                                                                                                                                                     'und '
                                                                                                                                                                                                                                                                                                                                                                     'Übertragungsnetze '
