                                                                                                                                                                                                                                                                                                                                                                'dem '
                                                                                                                                                                                                                                                                                                                                                                'Muster '
                                                                                                                                                                                                                                                                                                                                                                '`Version-Netzebene-Typ-Teilnetz-Szenario(-sw)`, '
                                                                                                                                                                                                                                                                                                                                                                'z. '
                                                                                                                                                                                                                                                                                                                                                                'B. '
                                                                                                                                                                                                                                                                                                                                                                '`1-MV-rural--0-sw`: '
                                                                                                                                                                                                                                                                                                                                                                'Datensatzversion '
                                                                                                                                                                                                                                                                                                                                                                '1, '
                                                                                                                                                                                                                                                                                                                                                                'ein '
                                                                                                                                                                                                                                                                                                                                                                'ländliches '
                                                                                                                                                                                                                                                                                                                                                                'Mittelspannungsnetz, '
