                                                                                                                                                                                                                                                                                                                                                                'explizit '
                                                                                                                                                                                                                                                                                                                                                                'modellierten '
                                                                                                                                                                                                                                                                                                                                                                'Schaltern. '
                                                                                                                                                                                                                                                                                                                                                                'Die '
                                                                                                                                                                                                                                                                                                                                                                'Szenarien '
                                                                                                                                                                                                                                                                                                                                                                '1 '
                                                                                                                                                                                                                                                                                                                                                                'und '
                                                                                                                                                                                                                                                                                                                                                                '2 '
                                                                                                                                                                                                                                                                                                                                                                'sind '
