                                                                                                                                                                                                                'Knoten '
                                                                                                                                                                                                                'hat '
                                                                                                                                                                                                                'eine '
                                                                                                                                                                                                                'Nennspannung '
                                                                                                                                                                                                                '`vn_kv`; '
                                                                                                                                                                                                                'die '
                                                                                                                                                                                                                'Lastflussrechnung '
