                                                                                                                                                                                                                                                    'B. '
                                                                                                                                                                                                                                                    '20 '
                                                                                                                                                                                                                                                    'kV '
                                                                                                                                                                                                                                                    '→ '
                                                                                                                                                                                                                                                    '0,4 '
                                                                                                                                                                                                                                                    'kV). '
                                                                                                                                                                                                                                                    'Die '
                                                                                                                                                                                                                                                    'Bemessungsleistung '
                                                                                                                                                                                                                                                    '`sn_mva` '
                                                                                                                                                                                                                                                    'und '
                                                                                                                                                                                                                                                    'die '
                                                                                                                                                                                                                                                    'Kurzschlussspannung '
