                                                                                                                                                                                                                                                                             'angegeben '
                                                                                                                                                                                                                                                                             '– '
                                                                                                                                                                                                                                                                             'als '
                                                                                                                                                                                                                                                                             'Verhältnis '
                                                                                                                                                                                                                                                                             'der '
                                                                                                                                                                                                                                                                             'tatsächlichen '
                                                                                                                                                                                                                                                                             'Spannung '
                                                                                                                                                                                                                                                                             'zur '
                                                                                                                                                                                                                                                                             'Nennspannung. '
