                                                                                                                                                                                                                                                                             'p.u. '
                                                                                                                                                                                                                                                                             'entspricht '
                                                                                                                                                                                                                                                                             'der '
                                                                                                                                                                                                                                                                             'Nennspannung; '
                                                                                                                                                                                                                                                                             'typische '
                                                                                                                                                                                                                                                                             'europäische '
                                                                                                                                                                                                                                                                             'Planungsgrenzen '
                                                                                                                                                                                                                                                                             'für '
                                                                                                                                                                                                                                                                             'Verteilnetze '
                                                                                                                                                                                                                                                                             'liegen '
                                                                                                                                                                                                                                                                             'bei '
                                                                                                                                                                                                                                                                             '±5 '
                                                                                                                                                                                                                                                                             '% '
                                                                                                                                                                                                                                                                             'bis '
                                                                                                                                                                                                                                                                             '±10 '
                                                                                                                                                                                                                                                                             '% '
                                                                                                                                                                                                                                                                             '(EN '
                                                                                                                                                                                                                                                                             '50160). '
                                                                                                                                                                                                                                                                             'Per-unit-Werte '
                                                                                                                                                                                                                                                                             'machen '
                                                                                                                                                                                                                                                                             'unterschiedliche '
                                                                                                                                                                                                                                                                             'Spannungsebenen '
