                                                                                                                                                                                                                                                             'bzw. '
                                                                                                                                                                                                                                                             'die '
                                                                                                                                                                                                                                                             'Scheinleistung '
                                                                                                                                                                                                                                                             '(Transformatoren) '
                                                                                                                                                                                                                                                             'ins '
                                                                                                                                                                                                                                                             'Verhältnis '
