                                                                                                                                                                                                                                                                                                                                                   'B. '
                                                                                                                                                                                                                                                                                                                                                   'Spannungskollaps), '
                                                                                                                                                                                                                                                                                                                                                   'isolierte '
                                                                                                                                                                                                                                                                                                                                                   'Teilnetze '
