                                                                                                                                                                                                                                                                                                          'ob '
                                                                                                                                                                                                                                                                                                          'die '
                                                                                                                                                                                                                                                                                                          'Erzeugung '
                                                                                                                                                                                                                                                                                                          'dem '
                                                                                                                                                                                                                                                                                                          'Verbrauch '
                                                                                                                                                                                                                                                                                                          'zuzüglich '
                                                                                                                                                                                                                                                                                                          'der '
                                                                                                                                                                                                                                                                                                          'Netzverluste '
                                                                                                                                                                                                                                                                                                          'entspricht. '
                                                                                                                                                                                                                                                                                                          'Der '
